// Auto-trigger assigned agent when issue moves to in_review
// Uses local HTTP server at 8787 (child_process blocked by n8n sandbox)
const SK = $env.SUPABASE_SERVICE_ROLE_KEY;
const SUPA = '${NEXT_PUBLIC_SUPABASE_URL}';
const h = { apikey: SK, Authorization: 'Bearer ' + SK };
const TRIGGER_URL = 'http://127.0.0.1:8787/trigger-agent';

const staticData = $getWorkflowStaticData('global');
if (!staticData.triggered) staticData.triggered = {};
const now = Date.now();
for (const [id, ts] of Object.entries(staticData.triggered)) {
  if (now - ts > 7 * 24 * 60 * 60 * 1000) delete staticData.triggered[id];
}

const twoMinAgo = new Date(now - 2.5 * 60 * 1000).toISOString();
const issues = await helpers.httpRequest({
  method: 'GET',
  url: SUPA + '/rest/v1/issues?status=eq.in_review&updated_at=gt.' + twoMinAgo + '&select=id,task_key,title,assignee,acceptance_criteria',
  headers: h
});
if (!Array.isArray(issues) || !issues.length) return [{ json: { processed: 0 } }];

const AGENT_MAP = {
  'tester': 'tester', 'builder': 'builder', 'scout': 'scout', 'ops': 'ops',
  'kemuni-sme': 'kemuni-sme', 'vespera-sme': 'vespera-sme', 'main': 'main', 'po': 'po',
  'designer': 'designer', 'auditor': 'auditor', 'deployer': 'deployer',
};
const results = [];

for (const issue of issues) {
  if (staticData.triggered[issue.id]) continue;
  const agentId = AGENT_MAP[issue.assignee];
  if (!agentId) { results.push({ key: issue.task_key, action: 'skipped: no agent for ' + issue.assignee }); continue; }

  const message = `You have a new issue in in_review assigned to you.\n\n[${issue.task_key}] ${issue.title}\n\nAC: ${issue.acceptance_criteria || 'See issue for details'}\n\nReview, test, and transition to code_review when complete.`;
  try {
    await helpers.httpRequest({
      method: 'POST', url: TRIGGER_URL,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ agentId, message })
    });
    staticData.triggered[issue.id] = now;
    results.push({ key: issue.task_key, agent: agentId, action: 'triggered' });
  } catch(e) {
    results.push({ key: issue.task_key, action: 'error: ' + e.message });
  }
}
return [{ json: { processed: results.length, results } }];

